  NOTE c1a 52 713/512 69 0 - {"nominal":{"at":"2","duration":"1/4","provenance":{"kind":"inferred","source":"pilot-groove-analysis"},"state":"current"}}
  NOTE c1b 56 261/512 109 1/64 {"at":"2","duration":"1/4","state":"current"} -
