}
GROUP c2 anchor=4 delay=3/256 label="strum 2" WITH {"provenance":{"kind":"declared","source":"pilot-synthetic-author"},"performanceOrder":["c2a","c2b","c2c","c2d"]} {
  FIELDS id pitch duration velocity spread nominal extra
  NOTE c2a 56 601/512 56 0 {"at":"4","duration":"1/4","state":"current"} -
  NOTE c2b 60 245/128 70 5/512 - -
  NOTE c2c 63 25/32 99 15/512 - {"nominal":{"at":"4","duration":"1/4","provenance":{"kind":"inferred","source":"pilot-groove-analysis"},"state":"current"}}
  NOTE c2d 68 49/128 68 21/512 {"at":"4","duration":"1/4","provenance":{"kind":"declared","source":"pilot-synthetic-author"}} -
